export type LineStatus = "발송" | "미발송" | "예약";

export interface ReportLine {
  key: string;
  memberId: string;
  kind: string;
  dueAt: LocalDateTime;
  sendAt: LocalDateTime;
  ticket: string;
  device: string;
  status: LineStatus;
